const TOOLS = ['HubSpot', 'QuickBooks', 'Xero', 'Stripe', 'Gmail', 'Outlook', 'Slack', 'Salesforce', 'Google Drive', 'Notion', 'Airtable', 'Calendly', 'DocuSign', 'Zendesk', 'Shopify', 'Mailchimp'];
const DEPTS = [
  { name: 'Software Dev', icon: 'code', lead: 'Build Lead', cap: 4000, used: 2400, outcome: 'Ship customer-facing features and internal tools without growing an engineering team.', agents: [['Feature Builder', 'Assisted'], ['QA Tester', 'Auto'], ['Bug Triage', 'Auto'], ['Release Notes', 'Auto']], human: 'What gets built, and every release.', assist: 'Specs, and a review of every change.', auto: 'Testing, fixes and release prep overnight.' },
  { name: 'Engineering', icon: 'cog', lead: 'Systems Lead', cap: 2000, used: 900, outcome: 'Keep your tools connected, fast and online, so nothing breaks quietly.', agents: [['Integration Builder', 'Assisted'], ['Data Sync', 'Auto'], ['Uptime Monitor', 'Auto'], ['Security Patching', 'Assisted']], human: 'New vendors, access and spend.', assist: 'Architecture options for your review.', auto: 'Monitoring, alerts and maintenance.' },
  { name: 'Design', icon: 'pen', lead: 'Creative Lead', cap: 1200, used: 640, outcome: 'On-brand pages, decks and assets in hours instead of weeks.', agents: [['Page Designer', 'Assisted'], ['Deck Builder', 'Assisted'], ['Brand Assets', 'Auto'], ['Screen Mockups', 'Assisted']], human: 'Brand direction and final sign-off.', assist: 'Drafts and variations to choose from.', auto: 'Resizing, exports and asset upkeep.' },
  { name: 'Marketing', icon: 'megaphone', lead: 'Growth Lead', cap: 2500, used: 1850, outcome: 'A content and campaign engine that publishes every day, not when someone finds time.', agents: [['Content Engine', 'Assisted'], ['SEO & Web', 'Auto'], ['Email Campaigns', 'Assisted'], ['Social Scheduler', 'Auto'], ['Performance Reports', 'Auto']], human: 'Positioning, offers and budget.', assist: 'Campaign drafts and message tests.', auto: 'Publishing, scheduling and reporting.' },
  { name: 'Sales', icon: 'trend', lead: 'Pipeline Lead', cap: 1500, used: 1120, outcome: 'No lead waits and no follow-up gets forgotten.', agents: [['SDR Outreach', 'Assisted'], ['Lead Research', 'Auto'], ['Deal Follow-up', 'Auto'], ['CRM Hygiene', 'Auto'], ['Objection Handler', 'Assisted']], human: 'Key conversations and pricing calls.', assist: 'Personal outreach drafts and call prep.', auto: 'Enrichment, follow-ups and CRM updates.' },
  { name: 'Deals', icon: 'handshake', lead: 'Deal Desk Lead', cap: 800, used: 380, outcome: 'Proposals and contracts out the same day the conversation ends.', agents: [['Proposal Writer', 'Assisted'], ['Quote Builder', 'Assisted'], ['Contract Drafts', 'Assisted'], ['Signature Chaser', 'Auto']], human: 'Terms and every final offer.', assist: 'Proposals drafted from call notes.', auto: 'Reminders and signature chasing.' },
  { name: 'Operations', icon: 'workflow', lead: 'Ops Lead', cap: 1000, used: 520, outcome: 'Processes that run the same way every time, without you chasing anyone.', agents: [['Onboarding', 'Auto'], ['Scheduling', 'Auto'], ['Task Routing', 'Auto'], ['Doc Processing', 'Auto'], ['Status Updates', 'Auto']], human: 'Priorities and exceptions.', assist: 'SOPs and workload planning.', auto: 'Routing, reminders and a daily brief.' },
  { name: 'Finance', icon: 'landmark', lead: 'Finance Lead', cap: 900, used: 410, outcome: 'Know where your money stands every single morning.', agents: [['Invoicing', 'Auto'], ['Reconciliation', 'Auto'], ['Collections', 'Auto'], ['Expense Tracking', 'Auto'], ['Cash Reports', 'Assisted']], human: 'Payments and spend.', assist: 'Forecasts and variance notes.', auto: 'Invoices, reconciliation, cash snapshot.' },
  { name: 'Legal', icon: 'scale', lead: 'Compliance Lead', cap: 700, used: 300, outcome: 'Contracts and policies checked before they turn into risks.', agents: [['Contract Review', 'Assisted'], ['Clause Flags', 'Assisted'], ['Policy Drafts', 'Assisted'], ['Renewal Tracker', 'Auto']], human: 'Every signature, with licensed counsel.', assist: 'Clause flags and suggested redlines.', auto: 'Renewal and deadline tracking.' },
  { name: 'Support', icon: 'headphones', lead: 'Support Lead', cap: 1200, used: 760, outcome: 'Customers answered in minutes, around the clock.', agents: [['Support Triage', 'Auto'], ['Reply Drafts', 'Assisted'], ['Help Center', 'Auto'], ['Escalations', 'Assisted']], human: 'Sensitive cases and refunds.', assist: 'Replies to complex tickets.', auto: 'Common questions answered 24/7.' }
];
const FAQS = [
  { q: 'Do I need a technical team?', a: 'No. We handle the build, the connections and the upkeep. Your team keeps using the tools they already know, and you approve important work from your phone or laptop.' },
  { q: 'Will AI make decisions without me?', a: 'Only the ones you allow. You set approval rules and a monthly spend cap for each department. Anything strategic, financial or client-facing waits for a human sign-off. That is the Co-Pilot Rule.' },
  { q: 'What happens on the free call?', a: 'In 15 minutes David maps one process that eats your week, estimates what it costs you, and shows where agents fit. You leave with clear next steps whether or not you work with us.' },
  { q: 'How is the price decided?', a: 'There is no rate card. After the audit we price the work around the size of your business, what we learned, and what you need most, then agree the final terms together.' },
  { q: 'Is my data safe?', a: 'Agents work inside your existing tools with only the access you grant, and you can revoke it at any time. We walk through exactly what connects to what on your call.' },
  { q: 'How long until something is live?', a: 'Your proposal includes a timeline for the first live workflow: [typical time to first workflow].' }
];
const AGENT_TOTAL = DEPTS.reduce((n, d) => n + d.agents.length, 0);
const fmt = (n) => n.toLocaleString('en-US');
const ON = { bg: 'var(--ink)', fg: 'var(--ink-text)', bd: 'var(--ink)' };
const OFF = { bg: 'var(--surface)', fg: 'var(--text)', bd: 'var(--border-2)' };

class Component extends DCLogic {
  constructor(...args) {
    super(...args);
    this.state = { navOpen: false, filmPaused: false, team: 8, rate: 55, hrs: 12, tools: [], dept: 4, faq: 0, subEmail: '', subDone: false, subError: false };
  }

  toggleTool(t) {
    const has = this.state.tools.indexOf(t) >= 0;
    this.setState({ tools: has ? this.state.tools.filter((x) => x !== t) : this.state.tools.concat([t]) });
  }

  subscribe() {
    if (/\S+@\S+\.\S+/.test(this.state.subEmail)) this.setState({ subDone: true, subError: false });
    else this.setState({ subError: true });
  }

  renderVals() {
    const s = this.state;
    const leak = s.team * s.rate * s.hrs * 52;
    const d = DEPTS[s.dept];
    return {
      theme: (this.props.theme ?? 'light') === 'dark' ? 'dark' : 'light',
      navOpen: s.navOpen,
      navExpanded: s.navOpen ? 'true' : 'false',
      navBtnBg: s.navOpen ? 'var(--surface-2)' : 'transparent',
      toggleNav: () => this.setState({ navOpen: !s.navOpen }),
      closeNav: () => this.setState({ navOpen: false }),

      marquee: LOGOS.concat(LOGOS).map((t, i) => ({ title: t.title, path: t.path, key: String(i % LOGOS.length) })),
      agentTotal: AGENT_TOTAL,

      filmClass: s.filmPaused ? 'paused' : '',
      filmPlaying: !s.filmPaused, filmPaused: s.filmPaused,
      filmLabel: s.filmPaused ? 'Play the walkthrough' : 'Pause the walkthrough',
      toggleFilm: () => this.setState({ filmPaused: !s.filmPaused }),

      team: s.team, rate: s.rate, hrs: s.hrs,
      onTeam: (e) => this.setState({ team: Number(e.target.value) }),
      onRate: (e) => this.setState({ rate: Number(e.target.value) }),
      onHrs: (e) => this.setState({ hrs: Number(e.target.value) }),
      calcTools: TOOLS.map((t) => {
        const sel = s.tools.indexOf(t) >= 0;
        return { label: t, pressed: sel ? 'true' : 'false', ...(sel ? ON : OFF), pick: () => this.toggleTool(t) };
      }),
      toolCount: s.tools.length,
      leakFmt: '$' + fmt(leak),
      autoFmt: '$' + fmt(Math.round(leak * 0.6)),

      depts: DEPTS.map((x, i) => ({
        name: x.name, count: String(x.agents.length), icon: ICONS[x.icon],
        bg: i === s.dept ? 'var(--em-soft)' : 'transparent',
        iconColor: i === s.dept ? 'var(--em-text)' : 'var(--text-3)',
        weight: i === s.dept ? 600 : 400,
        current: i === s.dept ? 'true' : 'false',
        pick: () => this.setState({ dept: i })
      })),
      dept: d,
      deptIcon: ICONS[d.icon],
      deptCount: d.agents.length,
      deptAgents: d.agents.map((a) => ({ name: a[0], mode: a[1] === 'Auto' ? 'Runs on its own' : 'You review', dot: a[1] === 'Auto' ? 'var(--em)' : 'var(--amber)' })),
      capUsed: '$' + fmt(d.used),
      capMax: '$' + fmt(d.cap),
      capPct: Math.round((d.used / d.cap) * 100) + '%',

      faqs: FAQS.map((f, i) => ({
        q: f.q, a: f.a, open: s.faq === i, closed: s.faq !== i, expanded: s.faq === i ? 'true' : 'false',
        signBg: s.faq === i ? 'var(--em-soft)' : 'var(--surface-2)',
        signFg: s.faq === i ? 'var(--em-text)' : 'var(--text-2)',
        toggle: () => this.setState({ faq: s.faq === i ? -1 : i })
      })),

      subEmail: s.subEmail, subDone: s.subDone, subNotDone: !s.subDone, subError: s.subError,
      subInvalid: s.subError ? 'true' : 'false',
      subBorder: s.subError ? 'var(--error)' : 'var(--border-2)',
      onSubEmail: (e) => this.setState({ subEmail: e.target.value, subError: false }),
      subscribe: () => this.subscribe(),
      onSubKey: (e) => { if (e.key === 'Enter') { e.preventDefault(); this.subscribe(); } }
    };
  }
}

export default Component;
